'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const pretty=d=>new Date(d+'T12:00:00').toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'short'});
const uid=()=>crypto.randomUUID();
let db,records=[],doses=[],selected=localDate(),month=new Date(new Date().getFullYear(),new Date().getMonth(),1),editing=null,draftPhotos=[],dirty=false,photoBusy=false,urls=[],tab='calendar';
function notify(t){$('#toast').textContent=t;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').textContent='',4200)}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('women-medicine-visit-notebook',1);r.onupgradeneeded=()=>{for(const n of ['records','doses','settings'])r.result.createObjectStore(n,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('blocked'))})}
function readAll(n){return new Promise((resolve,reject)=>{const r=db.transaction(n).objectStore(n).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function write(stores,fn){return new Promise((resolve,reject)=>{const tx=db.transaction(stores,'readwrite');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('abort'));try{fn(tx)}catch(e){tx.abort();reject(e)}})}
async function refresh(){[records,doses]=await Promise.all([readAll('records'),readAll('doses')]);render()}
function objectURL(blob){const u=URL.createObjectURL(blob);urls.push(u);return u}
function photosHTML(photos){return `<div class="photos">${photos.map(p=>`<div class="photo-wrap"><button class="photo-button" data-photo="${esc(p.id)}" aria-label="添付写真を大きく見る"><img src="${objectURL(p.blob)}" alt="添付した薬・処方箋の写真" loading="lazy"></button></div>`).join('')}</div>`}
function card(r){return `<article class="card record"><div class="record-top"><time datetime="${r.date}">${esc(r.date.replaceAll('-',' / '))}</time><button class="subtle" data-edit="${r.id}">編集</button></div><h3>${esc(r.hospital)}</h3><dl>${r.symptoms?`<dt>受診した理由・症状</dt><dd>${esc(r.symptoms)}</dd>`:''}</dl>${r.meds.map(m=>`<div class="pill"><strong>${esc(m.name)}</strong><span>${esc(m.instructions)||'飲み方の記入なし'}</span></div>`).join('')}${r.memo?`<dl><dt>メモ</dt><dd>${esc(r.memo)}</dd></dl>`:''}${photosHTML(r.photos)}</article>`}
function render(){urls.forEach(URL.revokeObjectURL);urls=[];const year=month.getFullYear(),mo=month.getMonth();$('#month').textContent=`${year}年 ${mo+1}月`;const n=new Date(year,mo+1,0).getDate();let html='<span></span>'.repeat(new Date(year,mo,1).getDay());for(let day=1;day<=n;day++){const d=localDate(new Date(year,mo,day)),marked=records.some(r=>r.date===d);html+=`<button data-date="${d}" class="${d===localDate()?'today ':''}${d===selected?'selected ':''}${marked?'marked':''}" aria-pressed="${d===selected}" aria-label="${mo+1}月${day}日${marked?'、受診記録あり':''}">${day}</button>`}$('#days').innerHTML=html;$('#selected-title').textContent=pretty(selected);const dayRecords=records.filter(r=>r.date===selected);$('#day-count').textContent=`受診 ${dayRecords.length}件`;$('#day-records').innerHTML=dayRecords.length?dayRecords.map(card).join(''):'<div class="empty"><strong>受診の記録はありません</strong><p>下の「＋ 受診を記録する」から残せます。</p></div>';const meds=records.filter(r=>r.date<=selected).flatMap(r=>r.meds.map(m=>({...m,hospital:r.hospital})));$('#doses').innerHTML=meds.length?meds.map(m=>{const dose=doses.find(d=>d.id===selected+'_'+m.id),taken=!!dose?.taken;return `<div class="card dose"><button class="dose-button ${taken?'checked':''}" data-dose="${m.id}" aria-pressed="${taken}"><span class="check-circle" aria-hidden="true">${taken?'✓':''}</span><span class="dose-title">${esc(m.name)}<small>${esc(m.instructions)||'飲み方の記入なし'}</small></span><span class="dose-state">${taken?'飲んだ':'未チェック'}</span></button><label><input type="checkbox" data-stop="${m.id}" ${m.endDate&&m.endDate<=selected?'checked':''}>この日から服用を終了</label>${m.endDate&&m.endDate<=selected?'<p class="hint">服用を終了した薬です。</p>':''}</div>`}).join(''):'<div class="empty"><p>薬を登録すると、ここでチェックできます。</p></div>';$$('[data-dose]').forEach(b=>{const m=meds.find(m=>m.id===b.dataset.dose);b.disabled=!!(m.endDate&&m.endDate<=selected)});const filter=$('#history-month').value;const history=records.filter(r=>!filter||r.date.startsWith(filter)).sort((a,b)=>b.date.localeCompare(a.date));$('#history-records').innerHTML=history.length?history.map(card).join(''):'<div class="empty">受診の記録はありません</div>';}
function switchTab(name){tab=name;for(const n of ['calendar','history','storage'])$(`#${n}-view`).hidden=n!==name;$$('[data-tab]').forEach(b=>{if(b.dataset.tab===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});window.scrollTo(0,0)}
function addMed(m={id:uid(),name:'',instructions:'',endDate:null}){const el=document.createElement('div');el.className='med-field';el.dataset.id=m.id;el.dataset.end=m.endDate||'';el.innerHTML=`<label>薬の名前<input class="med-name" maxlength="200" value="${esc(m.name)}" placeholder="薬の袋に書かれた名前"></label><label>薬の飲み方<input class="med-instructions" maxlength="500" value="${esc(m.instructions)}" placeholder="例：朝・夕 食後に1錠"></label>`;$('#med-fields').append(el)}
function editRecord(id=null){editing=id;const r=records.find(r=>r.id===id);const f=$('#record-form');f.reset();f.elements.date.value=r?.date||selected;f.elements.hospital.value=r?.hospital||'';f.elements.symptoms.value=r?.symptoms||'';f.elements.memo.value=r?.memo||'';$('#med-fields').innerHTML='';(r?.meds.length?r.meds:[undefined]).forEach(addMed);draftPhotos=r?[...r.photos]:[];$('#editor-title').textContent=r?'受診記録を編集':'受診を記録';$('#form-error').textContent='';dirty=false;drawDraftPhotos();$('#editor').showModal();$('#editor').scrollTop=0}
function closeEditor(){if(photoBusy)return;if(dirty&&!confirm('まだ保存していない内容があります。保存せずに戻りますか？'))return;$('#editor').close();draftPhotos=[]}
function drawDraftPhotos(){$('#photo-previews').innerHTML=draftPhotos.map(p=>`<div class="photo-wrap"><button type="button" class="photo-button" data-draft-photo="${p.id}" aria-label="添付写真を大きく見る"><img src="${objectURL(p.blob)}" alt="保存する写真"></button><button type="button" class="photo-remove" data-remove-photo="${p.id}">この写真を外す</button></div>`).join('')}
function viewPhoto(p){$('#full-photo').src=objectURL(p.blob);$('#photo-viewer').showModal()}
async function compress(file){if(file.size>25*1024*1024)throw Error('写真は1枚25MB以下で選んでください。');const u=URL.createObjectURL(file);try{const img=new Image();img.src=u;await img.decode();const scale=Math.min(1,2200/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.9));if(!blob)throw Error();return {id:uid(),blob}}catch(e){throw Error(e.message?.includes('25MB')?e.message:'この写真は読み込めませんでした。JPEG・PNGの写真やスクリーンショットを選んでください。')}finally{URL.revokeObjectURL(u)}}
$('#photos').onchange=async e=>{const files=[...e.target.files];if(draftPhotos.length+files.length>10){$('#form-error').textContent='写真は10枚まで選べます。';e.target.value='';return}photoBusy=true;$('#save').disabled=true;$('#form-error').textContent='写真を準備しています…';try{const prepared=[];for(const f of files)prepared.push(await compress(f));draftPhotos.push(...prepared);dirty=true;drawDraftPhotos();$('#form-error').textContent=''}catch(e){$('#form-error').textContent=e.message}finally{photoBusy=false;$('#save').disabled=false;e.target.value=''}};
$('#record-form').oninput=()=>dirty=true;
$('#record-form').onsubmit=async e=>{e.preventDefault();if(photoBusy)return;const f=e.target;const meds=$$('.med-field').map(el=>({id:el.dataset.id,name:el.querySelector('.med-name').value.trim(),instructions:el.querySelector('.med-instructions').value.trim(),endDate:el.dataset.end||null}));if(!f.elements.hospital.value.trim()){ $('#form-error').textContent='病院名を入力してください。';return}if(meds.some(m=>!m.name&&m.instructions)){$('#form-error').textContent='飲み方を入力した薬の名前も入れてください。';return}const r={id:editing||uid(),date:f.elements.date.value,hospital:f.elements.hospital.value.trim(),symptoms:f.elements.symptoms.value.trim(),memo:f.elements.memo.value.trim(),meds:meds.filter(m=>m.name),photos:[...draftPhotos]};$('#save').disabled=true;try{await write(['records'],tx=>tx.objectStore('records').put(r));selected=r.date;month=new Date(r.date+'T12:00:00');month.setDate(1);dirty=false;$('#editor').close();await refresh();switchTab('calendar');notify('受診記録を保存しました');navigator.storage?.persist?.().catch(()=>{})}catch{ $('#form-error').textContent='保存できませんでした。端末の空き容量を確認して、もう一度保存してください。入力内容はそのまま残っています。'}finally{$('#save').disabled=false}};
$('#cancel').onclick=closeEditor;$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor()});$('#add-med').onclick=()=>{addMed();dirty=true};$('#new-record').onclick=()=>editRecord();$('#close-photo').onclick=()=>$('#photo-viewer').close();$('#prev').onclick=()=>{month.setMonth(month.getMonth()-1);render()};$('#next').onclick=()=>{month.setMonth(month.getMonth()+1);render()};$('#today').onclick=()=>{selected=localDate();month=new Date(new Date().getFullYear(),new Date().getMonth(),1);render()};$('#history-month').onchange=render;$('#all-history').onclick=()=>{$('#history-month').value='';render()};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab)switchTab(b.dataset.tab);if(b.dataset.date){selected=b.dataset.date;render()}if(b.dataset.edit)editRecord(b.dataset.edit);if(b.dataset.photo)viewPhoto(records.flatMap(r=>r.photos).find(p=>p.id===b.dataset.photo));if(b.dataset.draftPhoto)viewPhoto(draftPhotos.find(p=>p.id===b.dataset.draftPhoto));if(b.dataset.removePhoto){draftPhotos=draftPhotos.filter(p=>p.id!==b.dataset.removePhoto);dirty=true;drawDraftPhotos()}if(b.dataset.dose){b.disabled=true;const id=selected+'_'+b.dataset.dose;try{await write(['doses'],tx=>tx.objectStore('doses').put({id,date:selected,medId:b.dataset.dose,taken:!doses.find(d=>d.id===id)?.taken}));await refresh();notify('服用の記録を保存しました')}catch{b.disabled=false;notify('保存できませんでした。もう一度お試しください。')}}});
document.addEventListener('change',async e=>{const id=e.target.dataset.stop;if(!id)return;const r=records.find(r=>r.meds.some(m=>m.id===id));const updated={...r,meds:r.meds.map(m=>m.id===id?{...m,endDate:e.target.checked?selected:null}:m)};try{await write(['records'],tx=>tx.objectStore('records').put(updated));await refresh()}catch{e.target.checked=!e.target.checked;notify('保存できませんでした。もう一度お試しください。')}});
const toDataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)});
$('#backup').onclick=async()=>{const b=$('#backup');b.disabled=true;try{const current=await readAll('records'),ds=await readAll('doses');const exported=[];for(const r of current){const photos=[];for(const p of r.photos)photos.push({id:p.id,data:await toDataURL(p.blob)});exported.push({...r,photos})}const blob=new Blob([JSON.stringify({format:'medicine-notebook',version:1,records:exported,doses:ds})],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`お薬手帳の控え_${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);$('#backup-status').textContent='控えを作成しました。「ファイル」などに保存されたことを確認してください。'}catch{notify('控えを作成できませんでした。もう一度お試しください。')}finally{b.disabled=false}};
function validateBackup(data){const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&localDate(new Date(s+'T12:00:00'))===s;const str=(s,n)=>typeof s==='string'&&s.length<=n;const id=s=>str(s,100)&&/^[a-zA-Z0-9_-]+$/.test(s);if(data?.format!=='medicine-notebook'||data.version!==1||!Array.isArray(data.records)||!Array.isArray(data.doses)||data.records.length>20000||data.doses.length>500000)throw Error();const ids=new Set(),medIds=new Set(),photoIds=new Set();for(const r of data.records){if(!id(r.id)||ids.has(r.id)||!date(r.date)||!str(r.hospital,200)||!r.hospital.trim()||!str(r.symptoms,5000)||!str(r.memo,5000)||!Array.isArray(r.meds)||!Array.isArray(r.photos)||r.photos.length>10)throw Error();ids.add(r.id);for(const m of r.meds){if(!id(m.id)||medIds.has(m.id)||!str(m.name,200)||!m.name.trim()||!str(m.instructions,500)||(m.endDate!==null&&!date(m.endDate)))throw Error();medIds.add(m.id)}for(const p of r.photos){if(!id(p.id)||photoIds.has(p.id)||typeof p.data!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$/.test(p.data)||p.data.length>35000000)throw Error();photoIds.add(p.id)}}const doseIds=new Set();for(const d of data.doses){if(!id(d.id)||doseIds.has(d.id)||!date(d.date)||!id(d.medId)||d.id!==d.date+'_'+d.medId||typeof d.taken!=='boolean')throw Error();doseIds.add(d.id)}}
$('#restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>250*1024*1024)throw Error();const data=JSON.parse(await file.text());validateBackup(data);if(!confirm(`${data.records.length}件の受診記録を控えから読み込みます。同じ記録がある場合は今の内容を残します。続けますか？`))return;const imported=[];for(const r of data.records){const photos=[];for(const p of r.photos){const [head,body]=p.data.split(',');const bytes=Uint8Array.from(atob(body),c=>c.charCodeAt(0));photos.push({id:p.id,blob:new Blob([bytes],{type:head.slice(5,head.indexOf(';'))})})}imported.push({...r,photos})}await write(['records','doses'],tx=>{for(const [store,items] of [['records',imported],['doses',data.doses]]){const s=tx.objectStore(store);for(const item of items){const request=s.get(item.id);request.onsuccess=()=>{if(!request.result)s.add(item)}}}});await refresh();notify('控えから記録を戻しました')}catch{notify('読み込めませんでした。正しい控えファイルと空き容量を確認してください。')}finally{e.target.value=''}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
async function init(){try{db=await openDB();await refresh();db.onversionchange=()=>{db.close();notify('画面を開き直してください。')};if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});const context=document.modelContext;if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'show_visit_calendar_date',description:'指定した日をカレンダーで表示します。記録の読み書きや送信はしません。',inputSchema:{type:'object',properties:{date:{type:'string'}},required:['date'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(!input||typeof input.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||localDate(new Date(input.date+'T12:00:00'))!==input.date)throw Error('有効な日付を指定してください');selected=input.date;month=new Date(selected+'T12:00:00');month.setDate(1);switchTab('calendar');render();return {date:selected}}})).catch(()=>{})}catch{}}}catch{$('#main').innerHTML='<div class="card storage-card"><h2>保存場所を開けませんでした</h2><p>通常のブラウザで開き直してください。改善しない場合は、ブラウザの保存設定と端末の空き容量を確認してください。</p></div>';$('#new-record').disabled=true;$$('nav button').forEach(b=>b.disabled=true)}}init();
